func (s AssetServiceServer) Erase(ctx context.Context, req *loft.AssetRef) (*loft.AssetEraseResponse, error) {
	p, err := AssetPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	var previous *loft.Asset
	if s.Rec != nil {
		images := snapshotOptions(s.Rec, loft.AssetService_Erase_FullMethodName)
		var v *ent.Asset
		var err error
		if images.Previous {
			v, err = st.snapshot(ctx, p, true)
		} else {
			v, err = st.Db.Asset.Query().Where(p).Select(asset.FieldId).Only(ctx)
		}
		if err != nil {
			if ent.IsNotFound(err) {
				return &loft.AssetEraseResponse{}, nil
			}
			return nil, err
		}

		k = v.Id
		if images.Previous {
			previous = s.image(v.Proto())
		}
		p = asset.And(p, asset.IdEQ(v.Id))
	}

	tx.Writing()
	u := st.Db.Asset.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:       loft.AssetService_Erase_FullMethodName,
			Key:      k,
			Previous: previous,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &loft.AssetEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// AssetPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a Asset is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasAssetWith`, where no narrowing of a Asset
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func AssetPick(req *loft.AssetRef) (predicate.Asset, error) {
	p, err := pickAsset(req)
	if err != nil {
		return nil, err
	}

	return asset.And(asset.DateErasedIsNil(), p), nil
}

func pickAsset(req *loft.AssetRef) (predicate.Asset, error) {
	switch req.WhichKey() {
	case loft.AssetRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return asset.IdEQ(v), nil
		}
	case loft.AssetRef_Tag_case:
		k := req.GetTag()
		ps := make([]predicate.Asset, 0, 2)
		ps = append(ps, asset.TagEQ(k.GetTag()))
		if p, err := TenantPick(k.GetTenant()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "tag.tenant: %s", err)
		} else {
			ps = append(ps, asset.HasTenantWith(p))
		}
		return asset.And(ps...), nil
	case loft.AssetRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Asset")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}

